<?php
declare(strict_types=1);
require __DIR__ . '/../projets/plateaux/lib.php';
function check(bool $ok, string $label): void { if (!$ok) throw new RuntimeException('FAIL: ' . $label); echo 'PASS: ' . $label . "\n"; }
function rejects(callable $call, int $status, string $label): void { try { $call(); } catch (Plateaux\TaskError $error) { check($error->status === $status, $label); return; } throw new RuntimeException('FAIL: ' . $label); }
$db = new PDO('sqlite::memory:', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$db->exec('CREATE TABLE todo_tasks (user_id INTEGER, id TEXT, title TEXT, priority TEXT DEFAULT "high", completed INTEGER DEFAULT 0, revision INTEGER DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT DEFAULT NULL, PRIMARY KEY(user_id,id))');
$db->exec("INSERT INTO todo_tasks (user_id, id, title, priority, completed, revision) VALUES (3, 'dddddddddddddddddddddddddddddddd', 'Ancienne tâche', 'low', 1, 5)");
$db->exec('CREATE TABLE todo_lists (user_id INTEGER, id TEXT, name TEXT COLLATE NOCASE, created_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,id), UNIQUE(user_id,name))');
$db->exec('ALTER TABLE todo_tasks ADD COLUMN list_id TEXT DEFAULT NULL');
$repo = new Plateaux\Tasks($db);
$legacy = $repo->all(3)[0];
check($legacy['listId'] === null && $legacy['priority'] === 'low' && $legacy['done'] && $legacy['revision'] === 5, 'une ancienne tâche reste dans Rappels avec son état, sa version et sa priorité');
$db->exec('DELETE FROM todo_tasks WHERE user_id = 3');
$input = ['id'=>str_repeat('a',32),'title'=>'  Tâche privée du premier compte  ','priority'=>'high','user_id'=>2];
$task = $repo->create(1,$input);
check($task['title'] === trim($input['title']) && $task['done'] === false && $task['revision'] === 1,'création et état initial');
check(count($repo->all(1)) === 1 && $repo->all(2) === [] && !isset($task['user_id']),'compte client ignoré, données isolées et réponse sans identifiant du compte');
check($repo->create(1,$input)['id'] === $task['id'] && count($repo->all(1)) === 1,'nouvel essai d’ajout sans doublon');
$repo->create(2,array_merge($input,['title'=>'Tâche du second compte','priority'=>'low']));
$changed = $repo->update(1,['id'=>$task['id'],'revision'=>1,'priority'=>'normal','user_id'=>2]);
check($changed['priority'] === 'normal' && $changed['revision'] === 2 && !$changed['done'] && $repo->all(2)[0]['priority'] === 'low','changement de priorité isolé et incrément de version');
rejects(fn()=>$repo->update(1,['id'=>$task['id'],'revision'=>1,'done'=>true]),409,'modification concurrente périmée refusée');
$checked = $repo->update(1,['id'=>$task['id'],'revision'=>2,'done'=>true]);
check($checked['done'] && $checked['priority'] === 'normal','cocher conserve la priorité et la tâche en base');
$again = $repo->update(1,['id'=>$task['id'],'revision'=>3,'done'=>false]);
check(!$again['done'] && $again['revision'] === 4,'décocher rétablit la tâche');
$private = $repo->create(1,array_merge($input,['id'=>str_repeat('b',32)]));
rejects(fn()=>$repo->update(2,['id'=>$private['id'],'revision'=>1,'done'=>true]),404,'modification d’une tâche étrangère refusée');
rejects(fn()=>$repo->remove(2,['id'=>$private['id'],'revision'=>1]),404,'suppression d’une tâche étrangère refusée');
$removed = $repo->remove(1,['id'=>$private['id'],'revision'=>1]);
check(count($repo->all(1)) === 1 && $removed['revision'] === 2 && (int)$db->query('SELECT COUNT(*) FROM todo_tasks')->fetchColumn() === 3,'une tâche supprimée est retirée de la liste');
rejects(fn()=>$repo->create(1,array_merge($input,['id'=>$private['id']])),409,'répéter un ajout ne rétablit pas une tâche supprimée');
foreach (['',str_repeat('é',161),"a\nligne","a\0b","\xff"] as $invalid) rejects(fn()=>$repo->create(1,array_merge($input,['title'=>$invalid])),422,'titres vides, longs, multiligne et UTF-8 malformé refusés');
check(Plateaux\title(str_repeat('é',160)) === str_repeat('é',160),'limite comptée en caractères Unicode');
foreach (['urgent',null,[],1] as $value) rejects(fn()=>$repo->update(1,['id'=>$task['id'],'revision'=>4,'priority'=>$value]),422,'priorité invalide refusée');
foreach (['false',0,1,null] as $value) rejects(fn()=>$repo->update(1,['id'=>$task['id'],'revision'=>4,'done'=>$value]),422,'état non booléen refusé');
rejects(fn()=>$repo->update(1,['id'=>$task['id'],'revision'=>'4','done'=>true]),422,'version de type incorrect refusée');
rejects(fn()=>$repo->create(1,array_merge($input,['id'=>"' OR 1=1 --"])),422,'identifiant arbitraire refusé');
$literal = '<img src=x onerror=alert(1)>';
check($repo->create(1,array_merge($input,['id'=>str_repeat('c',32),'title'=>$literal]))['title'] === $literal,'titre conservé comme texte pour le rendu échappé');
$listInput = ['id'=>str_repeat('e',32),'name'=>'  Maison  ','user_id'=>2];
$list = $repo->createList(1,$listInput);
check($list['name'] === 'Maison' && $repo->listCatalog(1)['lists'] === [$list] && $repo->listCatalog(2)['lists'] === [], 'les listes sont privées et persistantes');
check($repo->createList(1,$listInput) === $list, 'nouvel essai de création de liste sans doublon');
rejects(fn()=>$repo->createList(1,['id'=>str_repeat('f',32),'name'=>'maison']),409,'nom de liste en double refusé');
rejects(fn()=>$repo->createList(1,['id'=>str_repeat('f',32),'name'=>'Rappels']),409,'Rappels est réservé à la liste par défaut');
rejects(fn()=>$repo->create(2,array_merge($input,['id'=>str_repeat('f',32),'listId'=>$list['id']])),404,'ajout dans une liste étrangère refusé');
$move = ['id'=>$again['id'],'revision'=>$again['revision'],'listId'=>$list['id']];
rejects(fn()=>$repo->update(2,$move + ['done'=>true]),422,'une tâche ne peut pas être rattachée à une liste étrangère');
rejects(fn()=>$repo->update(1,$move),422,'une tâche existante ne peut pas changer de liste');
$new = $repo->create(1,array_merge($input,['id'=>str_repeat('f',32),'listId'=>$list['id']]));
check($new['listId'] === $list['id'],'une nouvelle tâche est enregistrée dans sa liste');
rejects(fn()=>$repo->update(1,['id'=>$new['id'],'revision'=>$new['revision'],'listId'=>null]),422,'le retrait du rattachement est aussi refusé');
$updated = $repo->update(1,['id'=>$new['id'],'revision'=>$new['revision'],'priority'=>'low','done'=>true]);
check($updated['listId'] === $list['id'] && $updated['priority'] === 'low' && $updated['done'],'la priorité et la complétion restent modifiables dans la liste d’origine');
$rename = ['id'=>$list['id'],'previousName'=>'Maison','name'=>'  Chez moi  '];
rejects(fn()=>$repo->renameList(2,$rename),404,'renommage d’une liste étrangère refusé');
$renamed = $repo->renameList(1,$rename);
check($renamed === ['id'=>$list['id'],'name'=>'Chez moi'] && $repo->renameList(1,$rename) === $renamed,'renommage enregistré et nouvelle tentative idempotente');
rejects(fn()=>$repo->renameList(1,array_replace($rename,['name'=>'Appartement'])),409,'renommage depuis un ancien nom refusé');
$otherList = $repo->createList(1,['id'=>str_repeat('a',32),'name'=>'Bureau']);
rejects(fn()=>$repo->renameList(1,['id'=>$otherList['id'],'previousName'=>'Bureau','name'=>'CHEZ MOI']),409,'nom de liste en double refusé au renommage');
$defaultRename = ['id'=>'rappels','previousName'=>'Rappels','name'=>'À faire'];
check($repo->renameList(1,$defaultRename) === ['id'=>'rappels','name'=>'À faire'],'la liste par défaut peut être renommée');
check($repo->listCatalog(1)['defaultListName'] === 'À faire' && count($repo->listCatalog(1)['lists']) === 2 && $repo->listCatalog(2)['defaultListName'] === 'Rappels','le nom par défaut est propre au compte et distinct des listes créées');
rejects(fn()=>$repo->renameList(1,['id'=>'rappels','previousName'=>'À faire','name'=>'Bureau']),409,'nom en double refusé pour la liste par défaut');
check($repo->all(1)[0]['listId'] === null && in_array($updated,$repo->all(1),true),'le renommage conserve les rattachements et le contenu des tâches');
echo "Tests Plateaux terminés.\n";
